import { Howl } from "howler";

// Files are generated by scripts/make-sfx.mjs.
const CRACKLE_VOL = 0.04;
let h: { needle: Howl; click: Howl; crackle: Howl } | null = null;
let level = 0.8;

const load = () =>
  (h ??= {
    needle: new Howl({ src: ["/assets/sfx/needle.wav"], volume: 0.5 }),
    click: new Howl({ src: ["/assets/sfx/click.wav"], volume: 0.35 }),
    crackle: new Howl({ src: ["/assets/sfx/crackle.wav"], loop: true, volume: CRACKLE_VOL * level }),
  });

export const sfx = {
  needle: () => load().needle.play(),
  click: () => load().click.play(),
  crackle(on: boolean) {
    const c = load().crackle;
    if (on && !c.playing()) c.play();
    if (!on) c.stop();
  },
  setVolume(v: number) {
    level = (v / 100) ** 2; // same taper as the music
    h?.crackle.volume(CRACKLE_VOL * level);
  },
};
